-- Catalog-derived from confirmed original Supabase project; not a historical migration
CREATE UNIQUE INDEX uq_ai_character_memories_winner_marker ON public.ai_character_memories USING btree (content) WHERE ((category = '당첨축하'::text) AND (content ~~ '[[WINNER:%'::text));
CREATE INDEX idx_ai_daily_presence_date ON public.ai_daily_presence USING btree (activity_date);
CREATE INDEX idx_ai_daily_presence_character_date ON public.ai_daily_presence USING btree (character_id, activity_date);
CREATE INDEX ai_event_entry_schedule_due_idx ON public.ai_event_entry_schedule USING btree (processed_at, participate_at);
CREATE INDEX ai_gift_inventory_status_queue_idx ON public.ai_gift_inventory USING btree (status, queue_no);
CREATE INDEX attendance_gift_inventory_status_queue_idx ON public.attendance_gift_inventory USING btree (status, queue_no);
CREATE INDEX attendance_event_member_idx ON public.attendance_records USING btree (event_id, member_id);
CREATE INDEX attendance_reward_deliveries_member_idx ON public.attendance_reward_deliveries USING btree (member_id, milestone_count DESC);
CREATE INDEX event_entries_event_idx ON public.event_entries USING btree (event_id);
CREATE INDEX event_entries_member_idx ON public.event_entries USING btree (member_id);
CREATE UNIQUE INDEX event_entries_one_member_one_event ON public.event_entries USING btree (event_id, member_id);
CREATE INDEX event_winners_event_idx ON public.event_winners USING btree (event_id);
CREATE UNIQUE INDEX event_winners_one_winner_per_event ON public.event_winners USING btree (event_id);
CREATE INDEX events_room_status_idx ON public.events USING btree (room_id, status);
CREATE UNIQUE INDEX events_auto_schedule_unique ON public.events USING btree (schedule_date, round_number) WHERE (auto_event = true);
CREATE INDEX gift_inventory_status_created_idx ON public.gift_inventory USING btree (status, created_at);
CREATE INDEX gift_inventory_assigned_member_idx ON public.gift_inventory USING btree (assigned_member_id, assigned_at DESC);
CREATE UNIQUE INDEX gift_inventory_queue_no_uidx ON public.gift_inventory USING btree (queue_no);
CREATE INDEX gift_inventory_available_queue_idx ON public.gift_inventory USING btree (status, queue_no) WHERE (status = 'available'::text);
CREATE INDEX group_messages_room_created_idx ON public.group_messages USING btree (room_id, created_at DESC);
CREATE INDEX group_messages_room_active_created_idx ON public.group_messages USING btree (room_id, created_at DESC) WHERE (is_deleted = false);
CREATE INDEX member_notes_member_idx ON public.member_notes USING btree (member_id);
CREATE INDEX members_nickname_idx ON public.members USING btree (nickname);
CREATE INDEX moderation_logs_target_idx ON public.moderation_logs USING btree (target_member_id, created_at DESC);
CREATE INDEX moderation_logs_operator_idx ON public.moderation_logs USING btree (operator_id, created_at DESC);
CREATE INDEX private_chats_operator_idx ON public.private_chats USING btree (operator_id);
CREATE INDEX private_chats_operator_status_updated_idx ON public.private_chats USING btree (operator_id, status, updated_at DESC);
CREATE INDEX private_chats_member_status_updated_idx ON public.private_chats USING btree (member_id, status, updated_at DESC);
CREATE INDEX private_messages_chat_created_idx ON public.private_messages USING btree (chat_id, created_at);
CREATE INDEX private_messages_unread_idx ON public.private_messages USING btree (chat_id, is_read);
CREATE INDEX private_messages_chat_active_created_idx ON public.private_messages USING btree (chat_id, created_at DESC) WHERE (is_deleted = false);
CREATE INDEX private_messages_chat_unread_idx ON public.private_messages USING btree (chat_id, sender_id, created_at DESC) WHERE ((is_deleted = false) AND (is_read = false));
CREATE INDEX profiles_group_joined_at_idx ON public.profiles USING btree (group_joined_at);
CREATE INDEX profiles_real_name_lookup_idx ON public.profiles USING btree (real_name);
CREATE INDEX push_subscriptions_user_id_idx ON public.push_subscriptions USING btree (user_id);
CREATE INDEX room_members_member_idx ON public.room_members USING btree (member_id);
CREATE INDEX room_restrictions_lookup_idx ON public.room_restrictions USING btree (room_id, member_id, restriction_type);
CREATE INDEX vip_daily_attendance_member_date_idx ON public.vip_daily_attendance USING btree (member_id, attendance_date DESC);
CREATE UNIQUE INDEX vip_surprise_one_real_member ON public.vip_surprise_process_runs USING btree (member_id) WHERE (source_type = 'real'::text);
CREATE INDEX vip_surprise_due_runs ON public.vip_surprise_process_runs USING btree (status, scheduled_start_at, scheduled_finish_at);
